c28438","field":"label","lang":"hr","value":"Trgovine"},{"model":"category","record_id":"ed8a3ff7-a5ff-4550-a3dc-72a4fd244adb","field":"label","lang":"fr","value":"Boulangeries"},{"model":"category","record_id":"ed8a3ff7-a5ff-4550-a3dc-72a4fd244adb","field":"label","lang":"nl","value":"Bakkerijen"},{"model":"category","record_id":"ed8a3ff7-a5ff-4550-a3dc-72a4fd244adb","field":"label","lang":"hr","value":"Pekarnice"},{"model":"category","record_id":"096654fc-ae40-47e3-8b41-2a27778ee5d7","field":"label","lang":"fr","value":"Stations-service"},{"model":"category","record_id":"096654fc-ae40-47e3-8b41-2a27778ee5d7","field":"label","lang":"nl","value":"Tankstations"},{"model":"category","record_id":"096654fc-ae40-47e3-8b41-2a27778ee5d7","field":"label","lang":"hr","value":"Benzinske postaje"},{"model":"category","record_id":"a5b6c0f8-af9a-420d-84dc-7f14aa16c0e4","field":"label","lang":"fr","value":"Distributeurs automatiques"},{"model":"category","record_id":"a5b6c0f8-af9a-420d-84dc-7f14aa16c0e4","field":"label","lang":"nl","value":"Geldautomaten"},{"model":"category","record_id":"a5b6c0f8-af9a-420d-84dc-7f14aa16c0e4","field":"label","lang":"hr","value":"Bankomati"},{"model":"category","record_id":"56a7ce74-5a1c-4ccb-ac29-36e1cb191219","field":"label","lang":"fr","value":"Pharmacies"},{"model":"category","record_id":"56a7ce74-5a1c-4ccb-ac29-36e1cb191219","field":"label","lang":"nl","value":"Apotheken"},{"model":"category","record_id":"56a7ce74-5a1c-4ccb-ac29-36e1cb191219","field":"label","lang":"hr","value":"Ljekarne"},{"model":"category","record_id":"d1066326-35fd-43fa-9c7a-3ee623283411","field":"label","lang":"fr","value":"Santé"},{"model":"category","record_id":"d1066326-35fd-43fa-9c7a-3ee623283411","field":"label","lang":"nl","value":"Gezondheidszorg"},{"model":"category","record_id":"d1066326-35fd-43fa-9c7a-3ee623283411","field":"label","lang":"hr","value":"Zdravstvena skrb"},{"model":"category","record_id":"36f99b4b-4068-48ba-b4e2-2d511b59e990","field":"label","lang":"fr","value":"Sites d’intérêt"},{"model":"category","record_id":"36f99b4b-4068-48ba-b4e2-2d511b59e990","field":"label","lang":"nl","value":"Bezienswaardigheden"},{"model":"category","record_id":"36f99b4b-4068-48ba-b4e2-2d511b59e990","field":"label","lang":"hr","value":"Znamenitosti"}]$rollout_rows$::jsonb)
    AS v(model text, record_id uuid, field text, lang text, value text)
  WHERE lang IN ('fr','nl','hr')
  ON CONFLICT (model, record_id, field, lang) DO NOTHING;
  GET DIAGNOSTICS inserted_count = ROW_COUNT;
  SELECT evidence::jsonb INTO after_state FROM (-- Read-only. 'camping-menina' is one of the four approved production slugs.
WITH t AS (
  SELECT id, slug, name, subtitle, address, hero_url, living_guide_hero_url, logo_url
  FROM tenants WHERE slug = 'camping-menina'
), s AS (
  SELECT s.* FROM sections s JOIN t ON t.id=s.tenant_id WHERE s.deleted_at IS NULL
), c AS (
  SELECT c.* FROM categories c JOIN s ON s.id=c.section_id WHERE c.deleted_at IS NULL
), i AS (
  SELECT i.* FROM items i JOIN c ON c.id=i.category_id WHERE i.deleted_at IS NULL
), r AS (
  SELECT 'tenant' AS model,id FROM t UNION ALL SELECT 'section',id FROM s
  UNION ALL SELECT 'category',id FROM c UNION ALL SELECT 'item',id FROM i
), tr AS (
  SELECT tr.* FROM translations tr JOIN r ON r.model=tr.model AND r.id=tr.record_id
)
SELECT jsonb_build_object(
  'slug', 'camping-menina'::text,
  'source', md5(jsonb_build_object(
    'tenants',(SELECT jsonb_agg(t ORDER BY id) FROM t),
    'sections',(SELECT jsonb_agg(s ORDER BY id) FROM s),
    'categories',(SELECT jsonb_agg(c ORDER BY id) FROM c),
    'items',(SELECT jsonb_agg(i ORDER BY id) FROM i)
  )::text),
  'legacy', (SELECT jsonb_object_agg(lang, jsonb_build_object('count',n,'md5',digest))
    FROM (SELECT l.lang, count(tr.id) AS n,
      md5(COALESCE(jsonb_agg(to_jsonb(tr) ORDER BY tr.id)
        FILTER (WHERE tr.id IS NOT NULL),'[]'::jsonb)::text) AS digest
      FROM (VALUES ('sl'),('en'),('de'),('it')) l(lang)
      LEFT JOIN tr ON tr.lang=l.lang GROUP BY l.lang) q),
  'snapshot',(SELECT md5(p.content::text) FROM published_snapshots p JOIN t ON t.id=p.tenant_id),
  'snapshotPublishedAt',(SELECT p.published_at FROM published_snapshots p JOIN t ON t.id=p.tenant_id)
)::text AS evidence) evidence_query;
  IF after_state IS DISTINCT FROM before_state THEN
    RAISE EXCEPTION 'Protected data changed; all inserts rolled back.';
  END IF;
  RAISE NOTICE 'camping-menina: inserted % draft rows; repeated execution inserts zero; protected checksums unchanged.', inserted_count;
END
$rollout$;
COMMIT;
